//! The TS rulebooks against the compiled covenant: replays
//! test/vectors/differential.json (generated by test/differential/generate.ts
//! from src/) through the browser's transaction builder, which runs every
//! input on the real script engine.
//!
//! Each vector is one spend of one covenant UTXO plus the TS verdict on it.
//! An accepted vector must build; a refused one must be refused BY THE SCRIPT
//! ENGINE, never earlier (a spec the builder cannot even assemble would pass a
//! rejection vacuously). Coverage is asserted too: every door of every actor
//! is seen accepted and script-refused, and every state field of every actor
//! is seen mutated and refused, so a generator regression cannot quietly
//! hollow the comparison out.

use std::collections::{BTreeMap, BTreeSet};

use fourk_wasm::builder::{build, Spec};
use secp256k1::{Keypair, Secp256k1, SecretKey};
use serde_json::{json, Value};

const COV_ID: &str = "abababababababababababababababababababababababababababababababab";
/// The wallet input continuations carry, as the app's do (its value does not
/// matter to the script; the builder does not balance values).
const FUND: u64 = 5_000_000;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn pk(seed: u8) -> String {
    let secp = Secp256k1::new();
    let kp = Keypair::from_secret_key(&secp, &SecretKey::from_slice(&[seed; 32]).unwrap());
    hex(&kp.x_only_public_key().0.serialize())
}

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../test/vectors/differential.json");
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    serde_json::from_str(&text).expect("vector file parses")
}

/// The spec for one vector, shaped as app/src/shared/lib/engine.ts builds it.
fn spec_of(file: &Value, v: &Value) -> Spec {
    let keys = file["keys"].as_array().unwrap();
    let input = &file["states"][v["input"].as_u64().unwrap() as usize];
    let mut inputs = vec![json!({
        "kind": "actor", "actor": input["actor"], "state": input["state"],
        "entry": v["entry"], "args": v["args"],
        "outpoint": { "txid": hex(&[0x22; 32]), "index": 0 },
        "value": input["value"], "daaScore": v["daaScore"], "coinbase": false,
        "covenantId": COV_ID, "sequence": v["sequence"],
    })];
    if let Some(k) = v["funding"].as_u64() {
        inputs.push(json!({
            "kind": "p2pk", "signer": k, "pubkey": keys[k as usize],
            "outpoint": { "txid": hex(&[0x33; 32]), "index": 0 },
            "value": FUND.to_string(), "daaScore": 0, "coinbase": false, "sequence": 0,
        }));
    }
    let mut outputs = Vec::new();
    if let Some(n) = v["next"].as_u64() {
        let next = &file["states"][n as usize];
        outputs.push(json!({
            "kind": "actor", "actor": next["actor"], "state": next["state"],
            "authorizingInput": 0, "covenantId": COV_ID, "value": next["value"],
        }));
    }
    for p in v["payouts"].as_array().unwrap() {
        outputs.push(json!({
            "kind": "script",
            "scriptPublicKey": format!("20{}ac", p["key"].as_str().unwrap()),
            "value": p["value"],
        }));
    }
    serde_json::from_value(json!({
        "network": "simnet", "lockTime": v["lockTime"], "inputs": inputs, "outputs": outputs,
    }))
    .expect("vector spec deserializes")
}

/// The artifact's ABI, as plain JSON.
fn abi() -> Value {
    serde_json::from_str(include_str!("../../contracts/build/artifact.json")).unwrap()
}

/// Every declared state field of `actor`, minus the runtime-filled ones.
fn fields_of(abi: &Value, actor: &str) -> BTreeSet<String> {
    abi["sil_abi"]["contracts"][actor]["runtime_state"]["fields"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| f["name"].as_str().unwrap().to_string())
        .filter(|name| !name.starts_with("gen__"))
        .collect()
}

#[test]
fn ts_rulebooks_and_compiled_covenant_agree() {
    let file = vectors();
    let keys: Vec<&str> = file["keys"].as_array().unwrap().iter().map(|k| k.as_str().unwrap()).collect();
    assert_eq!(keys, [pk(1), pk(2), pk(3)], "vector keys must be the seeds' pubkeys");
    let secrets: Vec<u8> = (1..=3u8).flat_map(|seed| [seed; 32]).collect();

    let mut failures = Vec::new();
    let mut accepted: BTreeSet<(String, String)> = BTreeSet::new();
    let mut refused: BTreeSet<(String, String)> = BTreeSet::new();
    let mut mutated: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let all = file["vectors"].as_array().unwrap();

    for (i, v) in all.iter().enumerate() {
        let actor = file["states"][v["input"].as_u64().unwrap() as usize]["actor"]
            .as_str()
            .unwrap()
            .to_string();
        let entry = v["entry"].as_str().unwrap().to_string();
        let class = v["class"].as_str().unwrap();
        let expect_accept = v["accept"].as_bool().unwrap();
        let result = build(&spec_of(&file, v), &secrets);
        let label = format!("#{i} {actor}::{entry} ({class})");
        match (expect_accept, result) {
            (true, Ok(_)) => {
                accepted.insert((actor, entry));
            }
            (true, Err(e)) => failures.push(format!("{label}: TS accepts, covenant refused: {e}")),
            (false, Ok(_)) => failures.push(format!("{label}: TS refuses, covenant accepted")),
            (false, Err(e)) if !e.is_script_rejection() => {
                failures.push(format!("{label}: refused before the engine ran: {e}"))
            }
            (false, Err(_)) => {
                if class == "mutant" {
                    let field = v["field"].as_str().unwrap().to_string();
                    mutated.entry(actor.clone()).or_default().insert(field);
                }
                refused.insert((actor, entry));
            }
        }
    }

    for f in failures.iter().take(400) {
        eprintln!("{f}");
    }
    assert!(failures.is_empty(), "{} of {} vectors disagree", failures.len(), all.len());

    // Coverage: both outcomes for every door, a refused mutant for every field.
    let abi = abi();
    for actor in [
        "FourkLobby",
        "FourkMatch",
        "FourkSimulV2Lobby",
        "FourkSimulV2",
    ] {
        let doors: Vec<String> = abi["sil_abi"]["contracts"][actor]["entries"]
            .as_object()
            .unwrap()
            .keys()
            .cloned()
            .collect();
        for door in doors {
            let key = (actor.to_string(), door.clone());
            assert!(accepted.contains(&key), "{actor}::{door} never seen accepted");
            assert!(refused.contains(&key), "{actor}::{door} never seen refused by the script");
        }
    }
    for actor in ["FourkMatch", "FourkSimulV2"] {
        let missing: Vec<String> = fields_of(&abi, actor)
            .difference(mutated.get(actor).unwrap_or(&BTreeSet::new()))
            .cloned()
            .collect();
        assert!(missing.is_empty(), "{actor} fields never mutated and refused: {missing:?}");
    }
}
